            let a = 0.5, s = 0.0, n = 0.0;
            for (let o = 0; o < oct; o++) { s += a * vnoise(x, y, z); n += a; x *= 2.03; y *= 2.03; z *= 2.03; a *= 0.5; }
            return s / n;
